pub use semio_framework_value_receiving::span::effect::{OriginalEffectAction,OriginalEffectAuthority,OriginalEffectCallbackMode,OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete};
struct PerformedScope<'turn,'decode>{control:&'turn mut NativeDecodeControl<'decode>,receipt:&'turn mut Option<semio_framework_value_control_contract::OriginalWorkPerformedReceipt>,claim:&'turn mut Option<Result<u128,ValueError>>,action:Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>}
impl Drop for PerformedScope<'_,'_>{fn drop(&mut self){*self.claim=Some(self.control.work.claim_performed_for_action(self.action,self.receipt).and_then(|()|self.control.work.performed_total_for_action(self.action)))}}

fn marker_mismatch(actual:Option<usize>,progress:RetainedCloneProgress)->Option<ValueError>{let differs=match actual{Some(bytes)=>bytes!=progress.retained_capacity_bytes,None=>progress.retained_capacity_bytes!=0};differs.then(||ValueError::literal(ValueRefusalKind::InvariantViolated,"native physical marker differs from retained child capacity").with_retained_progress(progress))}

/// 🚦️ Each pending callback requires its original recipient to resolve its actual outcome.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeReceivingEffectPhase{Empty,GrantStarted,Granted,EffectStarted,EffectFinished,ReceiptStarted,Settled}
/// 🎯️ Projects one actual preborn typed child slot without issuing Source metadata authority.
#[derive(Debug,PartialEq,Eq)]
pub struct NativeEffectCapturePlan{frame:usize,child:usize,extent:usize,error:std::any::TypeId,phase:NativeReceivingEffectPhase}
impl NativeEffectCapturePlan{pub fn frame_identity(&self)->usize{self.frame}pub fn child_destination(&self)->(usize,usize){(self.child,self.extent)}pub fn error_type(&self)->std::any::TypeId{self.error}pub fn phase(&self)->NativeReceivingEffectPhase{self.phase}}
pub use semio_framework_value_native_outcome::{NativeReceivingEffectError,NativeReceivingEffectFailure};
/// 🧳️ Keeps actual work and every original callback authority outside the operation stack.
pub struct NativeReceivingEffect<E:NativeReceivingEffectError=ValueError>{phase:NativeReceivingEffectPhase,maximum_work:Option<u64>,producer:ManuallyDrop<Option<OriginalEffectAction<RetainedCloneStep,E>>>,producer_reply:ManuallyDrop<Option<Result<RetainedCloneStep,E>>>,producer_refusal:ManuallyDrop<Option<ValueError>>,recipient:Option<OriginalConstructionIssuerIdentity>,action:Option<OriginalConstructionAction>,demand:RetirementDemand,grant:Option<RetainedCloneGrant>,actual:Option<usize>,unallocated_started:bool,work_settled:bool,work_commit_pending:bool,work_reported:u128,retiring:bool,actual_work:u128,performed:Option<semio_framework_value_control_contract::OriginalWorkPerformedReceipt>,partial_work:ManuallyDrop<Option<semio_framework_value_control_contract::OriginalWorkPartialOutcome>>,work_claim:ManuallyDrop<Option<Result<u128,ValueError>>>,work_proof:Option<semio_framework_value_control_contract::OriginalWorkActionProof>,work_action:Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>,work_issuer:Option<semio_framework_value_control_contract::OriginalWorkIssuerIdentity>,allocation:ManuallyDrop<Option<NativeDecodeAllocationProgress>>,outcome:ManuallyDrop<Option<NativeDecodeAllocationOutcome>>,child:ManuallyDrop<Option<RetainedWorkOutcome<RetainedCloneStep,E>>>,grant_refusal:ManuallyDrop<Option<ValueError>>,effect_refusal:ManuallyDrop<Option<ValueError>>,work_refusal:ManuallyDrop<Option<ValueError>>,work_reporting:ManuallyDrop<Option<ValueError>>,work_overrun:ManuallyDrop<Option<ValueError>>,receipt_refusal:ManuallyDrop<Option<ValueError>>}
impl<E:NativeReceivingEffectError> Default for NativeReceivingEffect<E>{fn default()->Self{Self{phase:NativeReceivingEffectPhase::Empty,maximum_work:None,producer:ManuallyDrop::new(None),producer_reply:ManuallyDrop::new(None),producer_refusal:ManuallyDrop::new(None),recipient:None,action:None,demand:Default::default(),grant:None,actual:None,unallocated_started:false,work_settled:false,work_commit_pending:false,work_reported:0,retiring:false,actual_work:0,performed:None,partial_work:ManuallyDrop::new(None),work_claim:ManuallyDrop::new(None),work_proof:None,work_action:None,work_issuer:None,allocation:ManuallyDrop::new(None),outcome:ManuallyDrop::new(None),child:ManuallyDrop::new(None),grant_refusal:ManuallyDrop::new(None),effect_refusal:ManuallyDrop::new(None),work_refusal:ManuallyDrop::new(None),work_reporting:ManuallyDrop::new(None),work_overrun:ManuallyDrop::new(None),receipt_refusal:ManuallyDrop::new(None)}}}
impl<E:NativeReceivingEffectError> NativeReceivingEffect<E>{
 pub fn capture_plan(&self)->NativeEffectCapturePlan{NativeEffectCapturePlan{frame:std::ptr::from_ref(self)as usize,child:std::ptr::from_ref(&*self.child)as usize,extent:std::mem::size_of::<Option<RetainedWorkOutcome<RetainedCloneStep,E>>>(),error:std::any::TypeId::of::<E>(),phase:self.phase}}
 /// 🧾️ Settles only the actual claimed partial receipt through its original Source producer.
 pub fn settle_partial_work(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{
  self.reconcile_performed(control)?;if !self.same_work(control){return Err(Self::invalid())}
  if self.partial_work.is_none(){
   if !control.work.partial_pending_for_action(self.work_action)?{return Ok(true)}
   match control.work.settle_partial_for_action_into(self.work_action,&mut self.partial_work){Ok(true)=>{},Ok(false)=>return Ok(false),Err(error)=>{self.work_commit_pending=true;if self.work_refusal.is_none(){*self.work_refusal=Some(error);return Err(Self::invalid())}return Err(error)}}
  }
  let(_,_,total,admitted,source)=self.partial_work.take().ok_or_else(Self::invalid)?.into_parts();self.actual_work=total;if !admitted&&self.work_overrun.is_none(){*self.work_overrun=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"original receiving work exceeded its original quote"))}if let Some(error)=source{self.work_commit_pending=true;if self.work_refusal.is_none(){*self.work_refusal=Some(error);return Err(Self::invalid())}return Err(error)}Ok(true)

 }
 fn recorded_work(&self)->u128{self.work_claim.as_ref().and_then(|result|result.as_ref().ok()).copied().unwrap_or(self.actual_work)}
 fn reconcile_performed(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if let Some(result)=self.work_claim.take(){self.actual_work=result?}if self.performed.is_some(){control.work.claim_performed_for_action(self.work_action,&mut self.performed)?;self.actual_work=control.work.performed_total_for_action(self.work_action)?}Ok(())}
 fn run_producer(&mut self,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant,operation:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{
  self.reconcile_performed(control)?;control.work.validate_action_source(self.work_action)?;control.work.issue_performed_for_action(self.work_action,&mut self.performed)?;
  if let Some(state)=self.allocation.as_mut(){state.start_operation()?}else{self.unallocated_started=true}
  let before=self.recorded_work();let maximum=control.pending_work();let mut scope=PerformedScope{control,receipt:&mut self.performed,claim:&mut self.work_claim,action:self.work_action};
  let turn={let sink=scope.receipt.as_mut().expect("original performed receipt issued");let mut effect=crate::RetainedAllocationEffect::new(grant,maximum,&mut self.actual,sink);operation(&mut *scope.control,&mut effect)};drop(scope);
  self.retain_child(turn);self.reconcile_performed(control)?;let actual=self.recorded_work().checked_sub(before).expect("original producer work regressed");if self.child.as_ref().is_some_and(|turn|turn.work!=actual)&&self.work_reporting.is_none(){*self.work_reporting=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"receiving work report differs from its original performed receipt"))}Ok(())
 }

 /// 🧳️ Recovers the same resident producer and transfers only its validated original reply.
 fn drive_original_producer<P>(&mut self,control:&mut NativeDecodeControl<'_>,authority:&mut OriginalEffectAuthority<P>,invoke:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>,&mut OriginalEffectAuthority<P>,&mut Option<OriginalEffectAction<RetainedCloneStep,E>>)->Result<bool,ValueError>)->Result<bool,ValueError>where P:OriginalEffectProducer<Output=RetainedCloneStep,Failure=E>{
  if self.phase!=NativeReceivingEffectPhase::EffectStarted||self.child.is_some(){return Err(Self::invalid())}
  if !self.settle_partial_work(control)?{return Ok(false)}
  let grant=self.effect_admitted(control)?;control.work.issue_performed_for_action(self.work_action,&mut self.performed)?;
  if let Some(state)=self.allocation.as_mut(){state.start_operation()?}else{self.unallocated_started=true}
  let remaining=u128::from(control.pending_work()).saturating_sub(self.recorded_work());let maximum=u64::try_from(remaining).map_err(|_|Self::invalid())?;
  let scope=PerformedScope{control,receipt:&mut self.performed,claim:&mut self.work_claim,action:self.work_action};
  let invoked={let sink=scope.receipt.as_mut().expect("original performed receipt issued");let mut effect=crate::RetainedAllocationEffect::new(grant,maximum,&mut self.actual,sink);invoke(&mut *scope.control,&mut effect,authority,&mut self.producer)};drop(scope);
  self.reconcile_performed(control)?;
  if let Err(error)=invoked{if self.producer_refusal.is_some(){return Err(error)}*self.producer_refusal=Some(error);return Ok(false)}
  if !self.settle_partial_work(control)?{return Ok(false)}
  if self.producer_reply.is_none(){if !self.producer.as_mut().ok_or_else(Self::invalid)?.transfer_reply(&mut self.producer_reply)?{return Ok(false)}}
  authority.finish(&mut self.producer)?;
  let result=self.producer_reply.take().ok_or_else(Self::invalid)?;self.retain_child(RetainedWorkOutcome{result,work:self.recorded_work()});Ok(true)
 }

 /// 🔭️ Returns the precise callback boundary held by the original frame.
 pub fn phase(&self)->NativeReceivingEffectPhase{self.phase}
 /// 🛟️ Loans the actual unsettled frame so its original control can resolve callbacks before close.
 pub fn has_pending_recovery(&self)->bool{self.phase!=NativeReceivingEffectPhase::Empty}
 pub fn pending_recovery(&mut self)->Option<&mut Self>{if self.has_pending_recovery(){Some(self)}else{None}}
 /// 📏️ Checks the exact demand retained before the original grant callback.
 /// 📏️ Borrows the retained original demand without inspecting the source.
 pub fn pending_demand(&self)->Option<RetirementDemand>{self.has_pending_recovery().then_some(self.demand)}
 pub fn matches_demand(&self,demand:RetirementDemand)->bool{self.demand==demand}
 /// 📏️ Returns the actual effect marker retained through an unwind.
 pub fn actual(&self)->Option<usize>{self.actual}
 /// 🧾️ Reads the submitted physical receipt without replacing the original child progress.
 pub fn construction_progress(&self)->Option<RetainedCloneProgress>{self.action.as_ref().and_then(OriginalConstructionAction::progress)}
 /// ⏱️ Borrows the actual retained child work without transferring its outcome.
 pub fn child_work(&self)->Option<u128>{self.child.as_ref().map(|_|self.recorded_work())}
 /// 🧾️ Reports whether the original work reservation has already settled.
 pub fn work_is_settled(&self)->bool{self.work_settled}
 /// 🔁️ Reports whether the original work settlement still needs its issuer.
 pub fn work_commit_is_pending(&self)->bool{self.work_commit_pending}
 /// 🧮️ Transfers a retained child work observation to its original caller only once.
 pub fn claim_child_work(&mut self)->u128{let total=self.recorded_work();let delta=total.checked_sub(self.work_reported).expect("original action work regressed");self.work_reported=total;delta}
 /// 🧾️ Observes the pending allocation progress without transferring its authority.
 pub fn allocation_progress(&self)->Option<&NativeDecodeAllocationProgress>{self.allocation.as_ref()}
 /// 🪪️ Resolves the original allocation callback through its receiving frame.
 pub fn recover_allocation_callback(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{if self.child.is_some()&&!self.valid_work_proof(control)?{return Err(Self::invalid())}if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control){return Err(Self::invalid())}let state=self.allocation.as_mut().ok_or_else(Self::invalid)?;control.recover_allocation_callback(state)}
 fn same_recipient(&self,control:&mut NativeDecodeControl<'_>)->bool{Self::recipient(control).is_ok_and(|recipient|Some(recipient.identity())==self.recipient)}
 /// 🛟️ Cleanup observes cancellation while retaining permission to drain its original owner.
 pub(crate) fn quote_retirement(&mut self,control:&mut NativeDecodeControl<'_>,demand:RetirementDemand,maximum_work:u64)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Empty||control.retirement.is_none(){return Err(Self::invalid())}self.retiring=true;self.maximum_work=Some(maximum_work);let owned_bytes=control.owned_bytes();let _=(control.callback)(super::super::NativeDecodeProgress{completed:control.completed,total:control.total,owned_bytes});self.work_issuer=control.work.recipient.as_ref().map(|loan|loan.identity());let recipient=Self::recipient(control)?;recipient.begin(demand,&mut self.action)?;self.recipient=Some(recipient.identity());self.demand=demand;self.phase=NativeReceivingEffectPhase::GrantStarted;recipient.quote(self.action.as_mut().ok_or_else(Self::invalid)?)?;self.recover_grant(control)?;Ok(())}
 fn same_work(&self,control:&NativeDecodeControl<'_>)->bool{self.work_issuer.is_some()&&self.work_issuer==control.work.recipient.as_ref().map(|loan|loan.identity())}
 fn valid_work_proof(&self,control:&NativeDecodeControl<'_>)->Result<bool,ValueError>{if !self.same_work(control)||!self.work_settled||self.work_proof.as_ref().map(|proof|proof.action_identity())!=self.work_action{return Ok(false)}match self.child_work().zip(self.work_proof.as_ref()){Some((actual,proof))=>control.work.validates(proof,actual),None=>Ok(false)}}
 fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native receiving frame requires its original recipient and callback phase")}
 fn recipient<'a,'control>(control:&'a mut NativeDecodeControl<'control>)->Result<&'a mut OriginalConstructionLoan<'control>,ValueError>{match control.construction.as_deref_mut(){Some(value)=>Ok(value),None=>Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native receiving requires its original construction recipient"))}}
 /// 🎟️ Retains the callback boundary before requesting the original physical grant.
 pub fn quote(&mut self,control:&mut NativeDecodeControl<'_>,demand:RetirementDemand)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Empty{return Err(Self::invalid())}control.checkpoint()?;self.work_issuer=control.work.recipient.as_ref().map(|loan|loan.identity());let recipient=Self::recipient(control)?;recipient.begin(demand,&mut self.action)?;self.recipient=Some(recipient.identity());self.demand=demand;self.phase=NativeReceivingEffectPhase::GrantStarted;recipient.quote(self.action.as_mut().ok_or_else(Self::invalid)?)?;self.recover_grant(control)?;Ok(())}
 /// 🪪️ Resolves a grant callback interrupted after its original recipient started it.
 pub fn recover_grant(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{if self.phase!=NativeReceivingEffectPhase::GrantStarted{return Err(Self::invalid())}let recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}let action=self.action.as_mut().ok_or_else(Self::invalid)?;let Some(reply)=recipient.recover_grant(action)?else{return Ok(false)};match reply{Ok(grant)=>{self.grant=Some(grant);if retained_clone_grant_admits(grant,self.demand){self.phase=NativeReceivingEffectPhase::Granted}else{recipient.cancel(action,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled}},Err(error)=>{*self.grant_refusal=Some(error);self.phase=NativeReceivingEffectPhase::Settled}}Ok(true)}
 /// ⛽️ Publishes this exact original work action before the producer can return or unwind.
 pub fn prepare_work(&mut self,control:&mut NativeDecodeControl<'_>,units:u64)->Result<Option<bool>,ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted||!self.same_work(control){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native receiving requires its original work action"))}control.work.prepare_for_action(units,&mut self.work_action)}
 /// ▶️ Executes one child only after the original allocation quote and retains its exact turn.
 pub fn effect(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut Option<usize>,RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{self.effect_controlled(control,|_,effect|{let grant=effect.grant();let turn=operation(effect.actual(),grant);let owed=turn.work.saturating_sub(effect.performed_work());if owed>0{let _=effect.performed(u64::try_from(owed).unwrap_or(u64::MAX));}turn})}
 /// 📤️ Retains a funded child that creates no allocation or allocation callback.
 pub fn effect_unallocated(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut Option<usize>,RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{self.effect_unallocated_controlled(control,|_,effect|{let grant=effect.grant();let turn=operation(effect.actual(),grant);let owed=turn.work.saturating_sub(effect.performed_work());if owed>0{let _=effect.performed(u64::try_from(owed).unwrap_or(u64::MAX));}turn})}
 fn effect_admitted(&self,control:&mut NativeDecodeControl<'_>)->Result<RetainedCloneGrant,ValueError>{if !self.same_work(control)||self.work_action.is_none()||self.work_action!=control.work.action_identity()||!control.has_pending_work()||control.work_quote_pending()||Self::recipient(control).ok().is_none_or(|recipient|Some(recipient.identity())!=self.recipient){return Err(Self::invalid())}control.work.validate_action_source(self.work_action)?;self.grant.ok_or_else(Self::invalid)}
 fn retain_child(&mut self,turn:RetainedWorkOutcome<RetainedCloneStep,E>){*self.child=Some(turn);let progress=match &self.child.as_ref().expect("resident original child").result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};if self.effect_refusal.is_none(){*self.effect_refusal=marker_mismatch(self.actual,progress)}}
 /// 🧵️ Lends the actual decoder only after its original allocation quote resides in this frame.
 pub fn effect_controlled(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted{return Err(Self::invalid())}self.effect_admitted(control)?;self.phase=NativeReceivingEffectPhase::EffectStarted;match control.prepare_allocation_effect(self.demand.capacity_bytes,&self.actual,&mut self.allocation,!self.retiring){super::super::allocation::NativeDecodeAllocationAdmission::Admitted=>{},super::super::allocation::NativeDecodeAllocationAdmission::Refused(outcome)=>{*self.outcome=Some(outcome);self.phase=NativeReceivingEffectPhase::EffectFinished;return Ok(())},super::super::allocation::NativeDecodeAllocationAdmission::Pending=>return Ok(())}self.resume_effect_controlled(control,operation)}
 /// 🎬️ Runs an untouched resident producer after only its original interrupted allocation quote recovered.
 pub fn resume_effect_controlled(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||self.actual.is_some()||self.child.is_some()||self.outcome.is_some()||self.unallocated_started||self.allocation.as_ref().is_none_or(|state|state.operation_started()||!matches!(state.phase(),super::super::allocation::NativeDecodeAllocationPhase::Absent|super::super::allocation::NativeDecodeAllocationPhase::QuoteAccepted)){return Err(Self::invalid())}let grant=self.effect_admitted(control)?;self.run_producer(control,grant,operation)}
 /// 🔁️ Reuses an untouched original allocation quote without issuing or executing a second effect.
 pub fn resume_effect(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut Option<usize>,RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{self.resume_effect_controlled(control,|_,effect|{let grant=effect.grant();let turn=operation(effect.actual(),grant);let owed=turn.work.saturating_sub(effect.performed_work());if owed>0{let _=effect.performed(u64::try_from(owed).unwrap_or(u64::MAX));}turn})}
 /// 🪡️ Lends the same paid decoder turn to a child that creates no allocation.
 pub fn effect_unallocated_controlled(&mut self,control:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted||self.demand.capacity_bytes!=0{return Err(Self::invalid())}let grant=self.effect_admitted(control)?;self.phase=NativeReceivingEffectPhase::EffectStarted;self.run_producer(control,grant,operation)?;self.phase=NativeReceivingEffectPhase::EffectFinished;Ok(())}
 /// 🧷️ Completes only the original allocation-free child already retained before an interruption.
 pub fn finish_unallocated(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.unallocated_started||self.allocation.is_some()||!self.valid_work_proof(control)?||Self::recipient(control)?.identity()!=self.recipient.ok_or_else(Self::invalid)?{return Err(Self::invalid())}let progress=match &self.child.as_ref().ok_or_else(Self::invalid)?.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};if self.actual.is_none()&&progress.retained_capacity_bytes!=0{return Err(Self::invalid())}if self.effect_refusal.is_none(){*self.effect_refusal=marker_mismatch(self.actual,progress)}self.phase=NativeReceivingEffectPhase::EffectFinished;Ok(())}
 /// 🧳️ Resolves the real retained child after an interrupted allocation-free action.
 pub fn resolve_unallocated_child(&mut self,control:&mut NativeDecodeControl<'_>,turn:RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),(ValueError,RetainedWorkOutcome<RetainedCloneStep,E>)>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||self.demand.capacity_bytes!=0||!self.unallocated_started||self.allocation.is_some()||self.child.is_some()||!self.same_recipient(control){return Err((Self::invalid(),turn))}*self.child=Some(turn);self.phase=NativeReceivingEffectPhase::EffectFinished;Ok(())}
 /// 🧳️ Resolves an interrupted child with its real retained result and work before allocation settlement.
 pub fn resolve_child(&mut self,control:&mut NativeDecodeControl<'_>,turn:RetainedWorkOutcome<RetainedCloneStep,E>)->Result<(),(ValueError,RetainedWorkOutcome<RetainedCloneStep,E>)>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control)||self.child.is_some()||self.allocation.as_ref().is_none_or(|state|!state.operation_started()){return Err((Self::invalid(),turn))}*self.child=Some(turn);let progress=match &self.child.as_ref().expect("retained original child").result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};*self.effect_refusal=marker_mismatch(self.actual,progress);Ok(())}
 /// 🧮️ Installs an actual owner-supplied marker only when it matches the retained child receipt.
 pub fn resolve_effect_marker(&mut self,control:&mut NativeDecodeControl<'_>,actual:Option<usize>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control){return Err(Self::invalid())}let turn=self.child.as_ref().ok_or_else(Self::invalid)?;let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};if self.actual.is_some()&&self.actual!=actual{return Err(Self::invalid())}if actual.is_none()&&progress.retained_capacity_bytes!=0{return Err(Self::invalid())}if self.effect_refusal.is_none(){*self.effect_refusal=marker_mismatch(actual,progress)}self.actual=actual;Ok(())}
 /// 🔁️ Retains the resolved allocation outcome before any construction receipt callback.
 pub fn finish_allocation(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectStarted||!self.same_recipient(control)||self.outcome.is_some()||(self.child.is_some()&&!self.valid_work_proof(control)?){return Err(Self::invalid())}let state=self.allocation.as_mut().ok_or_else(Self::invalid)?;if state.operation_started()&&self.child.is_none(){return Err(Self::invalid())}if let Some(turn)=self.child.as_ref(){let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};if self.actual.is_none()&&progress.retained_capacity_bytes!=0{return Err(Self::invalid())}if self.effect_refusal.is_none(){*self.effect_refusal=marker_mismatch(self.actual,progress)}}if !matches!(state.phase(),super::super::allocation::NativeDecodeAllocationPhase::Settled|super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused){if !control.settle_allocation_progress(state,self.actual)?{return Ok(())}}let state=self.allocation.take().ok_or_else(Self::invalid)?;match state.into_outcome(){Ok(outcome)=>*self.outcome=Some(outcome),Err(state)=>{*self.allocation=Some(state);return Err(Self::invalid())}}self.phase=NativeReceivingEffectPhase::EffectFinished;Ok(())}
 /// 🧾️ Commits the original held work and retains any independent refusal in this frame.
 pub fn settle_original_work(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{if !self.same_work(control)||self.child.is_none()||!matches!(self.phase,NativeReceivingEffectPhase::EffectStarted|NativeReceivingEffectPhase::EffectFinished)||!self.same_recipient(control)||self.work_settled{return Err(Self::invalid())}if !self.settle_partial_work(control)?{self.work_commit_pending=true;return Ok(false)}let actual=self.recorded_work();match control.work.commit_for_action(actual,self.work_action,&mut self.work_proof){Ok(accepted)=>{if !accepted&&self.work_overrun.is_none(){*self.work_overrun=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"original receiving work exceeded its original quote"))}},Err(error)=>{self.work_commit_pending=true;if self.work_refusal.is_none(){*self.work_refusal=Some(error);return Err(Self::invalid())}return Err(error)}}self.work_settled=true;self.work_commit_pending=false;Ok(true)}
 /// 🔁️ Retries only the original pending work commit while retaining its earlier refusal.
 pub fn retry_original_work(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{if !self.work_commit_pending||self.work_settled{return Err(Self::invalid())}self.settle_original_work(control)}
 /// ⛽️ Retains a separate original work settlement refusal without replacing any child cause.
 pub fn record_work_refusal(&mut self,control:&mut NativeDecodeControl<'_>,refusal:ValueError)->Result<(),(ValueError,ValueError)>{if !matches!(self.phase,NativeReceivingEffectPhase::Granted|NativeReceivingEffectPhase::EffectStarted|NativeReceivingEffectPhase::EffectFinished)||!self.same_recipient(control)||self.work_refusal.is_some(){return Err((Self::invalid(),refusal))}*self.work_refusal=Some(refusal);Ok(())}
 /// ⏪️ Cancels the original held work only when this frame proves no child effect began.
 pub fn cancel_unperformed_work(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if !self.same_recipient(control)||self.child.is_some()||self.actual.is_some()||self.unallocated_started{return Err(Self::invalid())}let unstarted=match self.phase{NativeReceivingEffectPhase::Granted=>true,NativeReceivingEffectPhase::EffectFinished=>self.outcome.as_ref().is_some_and(|outcome|outcome.actual.is_none()),NativeReceivingEffectPhase::EffectStarted=>self.allocation.as_ref().is_some_and(|state|!state.operation_started()&&state.phase()==super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused),_=>false};if !unstarted||!self.same_work(control){return Err(Self::invalid())}control.work.cancel_for_action(&mut self.work_action)}
 /// ⏪️ Leaves an admitted grant unused when the original work quote declined before any effect.
 pub fn cancel_unstarted(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::Granted{return Err(Self::invalid())}if self.work_action.is_some(){if !self.same_work(control){return Err(Self::invalid())}control.work.cancel_for_action(&mut self.work_action)?}let recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}recipient.cancel(self.action.as_mut().ok_or_else(Self::invalid)?,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled;Ok(())}
 /// 🧾️ Submits retained actual progress once under the unchanged original construction recipient.
 pub fn receipt(&mut self,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if self.phase!=NativeReceivingEffectPhase::EffectFinished||self.work_commit_pending||(self.child.is_some()&&!self.valid_work_proof(control)?){return Err(Self::invalid())}let recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}let action=self.action.as_mut().ok_or_else(Self::invalid)?;let Some(turn)=self.child.as_ref()else{if self.actual.is_some(){return Err(Self::invalid())}recipient.cancel(action,false,Default::default(),None)?;self.phase=NativeReceivingEffectPhase::Settled;return Ok(())};let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()};let grant=self.grant.ok_or_else(Self::invalid)?;let submitted=match self.actual{Some(bytes)=>RetainedCloneProgress{retained_capacity_bytes:bytes,..progress},None if progress.retained_capacity_bytes==0=>progress,None=>return Err(Self::invalid())};if (!progress.fits(grant)||!submitted.fits(grant))&&self.grant_refusal.is_none(){*self.grant_refusal=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"native child receipt exceeds original grant"))}self.phase=NativeReceivingEffectPhase::ReceiptStarted;if let Err(error)=recipient.post(action,submitted,self.actual){if action.phase()==super::OriginalConstructionPhase::Granted{self.phase=NativeReceivingEffectPhase::EffectFinished}return Err(error)}self.recover_receipt(control)?;Ok(())}
 /// 🪪️ Resolves an interrupted receipt without issuing it again or changing its owner.
 pub fn recover_receipt(&mut self,control:&mut NativeDecodeControl<'_>)->Result<bool,ValueError>{if self.phase!=NativeReceivingEffectPhase::ReceiptStarted{return Err(Self::invalid())}let recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}let Some(reply)=recipient.recover_accept(self.action.as_mut().ok_or_else(Self::invalid)?)?else{return Ok(false)};*self.receipt_refusal=reply.err();self.phase=NativeReceivingEffectPhase::Settled;Ok(true)}
 /// 📬️ Transfers the settled child, work and all independent refusals to its original caller.
 pub fn take(&mut self,control:&mut NativeDecodeControl<'_>)->Result<RetainedWorkOutcome<RetainedCloneStep,NativeReceivingEffectFailure<E>>,ValueError>{if self.phase!=NativeReceivingEffectPhase::Settled||self.partial_work.is_some()||self.producer.is_some()||self.producer_reply.is_some()||self.performed.is_some()||self.work_claim.is_some()||self.allocation.is_some()||self.work_commit_pending||self.action.is_none()||(self.work_action.is_some()&&self.work_proof.is_none()){return Err(Self::invalid())}if Self::recipient(control)?.identity()!=self.recipient.ok_or_else(Self::invalid)?{return Err(Self::invalid())}if self.work_proof.is_some(){if !self.valid_work_proof(control)?{return Err(Self::invalid())}control.work.finish_for_action(&mut self.work_proof,&mut self.work_action)?}let recipient=Self::recipient(control)?;if Some(recipient.identity())!=self.recipient{return Err(Self::invalid())}recipient.finish(&mut self.action)?;let progress=self.child.as_ref().map(|turn|match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.receiving_progress()}).unwrap_or_default();let reported=self.work_reported;let actual_work=self.recorded_work();let turn=self.child.take().unwrap_or_else(||RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0});let(step,primary)=match turn.result{Ok(step)=>(Some(step),None),Err(error)=>(None,Some(error))};let allocation=self.outcome.take();let allocation_failed=allocation.as_ref().is_some_and(|outcome|outcome.primary.is_some()||outcome.quote_refusal.is_some()||outcome.extent_refusal.is_some()||outcome.settlement_refusal.is_some());let grant_refusal=self.grant_refusal.take();let effect_refusal=self.effect_refusal.take();let work_refusal=self.work_refusal.take();let work_reporting=self.work_reporting.take();let work_overrun=self.work_overrun.take();let receipt_refusal=self.receipt_refusal.take();let producer_refusal=self.producer_refusal.take();let failed=producer_refusal.is_some()||primary.is_some()||grant_refusal.is_some()||effect_refusal.is_some()||work_refusal.is_some()||work_reporting.is_some()||work_overrun.is_some()||receipt_refusal.is_some()||allocation_failed;let result=if failed{Err(NativeReceivingEffectFailure{child:primary,producer_refusal,work_refusal,receiving:OriginalReceivingPrimary{retirement_failure:None,work_refusal:work_reporting,work_overrun,primary:effect_refusal,quote_refusal:grant_refusal,allocation_refusal:None,allocation_failure:None,native_allocation:allocation,receipt_refusal,progress}})}else{Ok(step.expect("settled child step"))};self.phase=NativeReceivingEffectPhase::Empty;self.maximum_work=None;self.recipient=None;self.action=None;self.grant=None;self.actual=None;self.unallocated_started=false;self.work_settled=false;self.work_commit_pending=false;self.work_reported=0;self.retiring=false;self.work_issuer=None;self.actual_work=0;Ok(RetainedWorkOutcome{result,work:actual_work.checked_sub(reported).expect("original action work already reported")})}
}
impl<E:NativeReceivingEffectError> Drop for NativeReceivingEffect<E>{fn drop(&mut self){assert!(std::thread::panicking()||self.phase==NativeReceivingEffectPhase::Empty,"native receiving frame requires original callback settlement and paid closure")}}

impl<E:NativeReceivingEffectError> crate::retirement::RetirementCursor for NativeReceivingEffect<E>{
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::retirement::RetirementStep{let _=effect.grant();if self.phase==NativeReceivingEffectPhase::Empty{crate::retirement::RetirementStep::Complete(0)}else{crate::retirement::RetirementStep::Failure(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original receiving callbacks and child work must settle before retirement").into(),0)}}
 fn terminal_is_empty(&self)->bool{self.phase==NativeReceivingEffectPhase::Empty}
}
/// ♻️ Retains the same receiving frame until its original callbacks have settled.
pub struct NativeReceivingEffectRetirement<E:NativeReceivingEffectError>{frame:Option<NativeReceivingEffect<E>>}
impl<E:NativeReceivingEffectError> Drop for NativeReceivingEffectRetirement<E>{fn drop(&mut self){assert!(std::thread::panicking()||self.frame.is_none(),"original receiving frame retirement requires paid closure")}}
impl<E:NativeReceivingEffectError> crate::retirement::RetireOwned for NativeReceivingEffect<E>{
 type RetirementCursor=Self;
 fn retirement_seed(self)->Self{self}
 fn retirement_ready(&self)->bool{self.phase==NativeReceivingEffectPhase::Empty}
 fn retirement_birth_bytes(&self)->Option<usize>{(self.phase==NativeReceivingEffectPhase::Empty).then_some(std::mem::size_of::<Self>())}
 fn controlled_retirement_supported()->bool{true}
}

#[cfg(test)]
mod marker_tests{
 use super::*;


 #[test]
 fn explicit_marker_never_invents_a_post_from_child_progress(){
  let corpus:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🌱️value/🛬️decode/🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for case in corpus["receivingMarkerCases"].as_array().unwrap(){let actual=case["actual"].as_u64().map(|value|value as usize);let retained=case["retained"].as_u64().unwrap()as usize;let progress=RetainedCloneProgress{retained_capacity_bytes:retained,..Default::default()};let error=marker_mismatch(actual,progress);assert_eq!(error.is_some(),case["mismatch"].as_bool().unwrap());if let Some(error)=error{assert_eq!(error.retained_progress(),progress);}}
 }


}


/// 🚦️ Returns actual settled custody or leaves the original action resident.
pub enum NativeReceivingEffectPoll<E:NativeReceivingEffectError>{Pending{work:u128},Complete(RetainedWorkOutcome<RetainedCloneStep,NativeReceivingEffectFailure<E>>)}
impl NativeDecodeControl<'_>{
 /// 🪢️ Runs one closure inside one original Work action on this control's own recipient; `None` means the quote was not admitted and nothing ran or was charged. The control handed to the closure carries the live work action: children may charge, checkpoint and read bytes but must never prepare_work.
 pub fn with_effect<R>(&mut self,grant:RetainedCloneGrant,maximum_work:u64,run:impl FnOnce(&mut Self,&mut crate::RetainedAllocationEffect<'_>)->R)->Result<Option<R>,ValueError>{
  let Some(mut open)=semio_framework_value_control_contract::OriginalEffectRun::begin(&mut self.work,grant,maximum_work)?else{return Ok(None)};
  let output={let mut effect=open.effect()?;run(self,&mut effect)};
  open.finish(&mut self.work,&mut 0)?;Ok(Some(output))
 }
 /// 🧵️ Drives the same resident producer through original work, allocation and construction replies.
 pub fn receive_effect<E:NativeReceivingEffectError>(&mut self,demand:RetirementDemand,maximum_work:u64,frame:&mut NativeReceivingEffect<E>,operation:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep,E>)->Result<NativeReceivingEffectPoll<E>,ValueError>{
  use NativeReceivingEffectPhase as Phase;
  if frame.phase()==Phase::Empty{frame.quote(self,demand)?}else if !frame.matches_demand(demand){return Err(ValueError::invariant("original receiving demand changed"))}
  if frame.phase()==Phase::GrantStarted&&!frame.recover_grant(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}
  if frame.phase()==Phase::Granted{match frame.prepare_work(self,maximum_work)?{None=>return Ok(NativeReceivingEffectPoll::Pending{work:0}),Some(false)=>frame.cancel_unstarted(self)?,Some(true)=>{}}}
  if frame.phase()==Phase::EffectStarted&&frame.child_work().is_none(){if let Some(progress)=frame.allocation_progress(){if matches!(progress.phase(),super::super::allocation::NativeDecodeAllocationPhase::QuoteStarted|super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused){if !frame.recover_allocation_callback(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:0})}}}}
  let fresh=frame.phase()==Phase::Granted;
  let resumed=frame.phase()==Phase::EffectStarted&&frame.child_work().is_none()&&frame.allocation_progress().is_some_and(|progress|!progress.operation_started()&&matches!(progress.phase(),super::super::allocation::NativeDecodeAllocationPhase::Absent|super::super::allocation::NativeDecodeAllocationPhase::QuoteAccepted));
  if fresh||resumed{if resumed{frame.resume_effect_controlled(self,operation)?}else if demand.capacity_bytes==0{frame.effect_unallocated_controlled(self,operation)?}else{frame.effect_controlled(self,operation)?}}
  self.finish_effect_poll(frame)
 }
 /// 🏭️ Lends one original effect to an actual producer whose reply remains in this frame.
 pub fn receive_original_effect<P>(&mut self,demand:RetirementDemand,maximum_work:u64,frame:&mut NativeReceivingEffect<P::Failure>,authority:&mut OriginalEffectAuthority<P>,invoke:impl FnOnce(&mut NativeDecodeControl<'_>,&mut crate::RetainedAllocationEffect<'_>,&mut OriginalEffectAuthority<P>,&mut Option<OriginalEffectAction<RetainedCloneStep,P::Failure>>)->Result<bool,ValueError>)->Result<NativeReceivingEffectPoll<P::Failure>,ValueError>where P:OriginalEffectProducer<Output=RetainedCloneStep>,P::Failure:NativeReceivingEffectError{
  use NativeReceivingEffectPhase as Phase;
  if frame.phase()==Phase::Empty{frame.maximum_work=Some(maximum_work);frame.quote(self,demand)?}else if !frame.matches_demand(demand)||frame.maximum_work!=Some(maximum_work){return Err(ValueError::invariant("original receiving demand or work ceiling changed"))}
  if frame.phase()==Phase::GrantStarted&&!frame.recover_grant(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}
  if frame.phase()==Phase::Granted{match frame.prepare_work(self,maximum_work)?{None=>return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()}),Some(false)=>frame.cancel_unstarted(self)?,Some(true)=>{frame.effect_admitted(self)?;frame.phase=Phase::EffectStarted;if demand.capacity_bytes!=0{match self.prepare_allocation_effect(demand.capacity_bytes,&frame.actual,&mut frame.allocation,!frame.retiring){super::super::allocation::NativeDecodeAllocationAdmission::Admitted=>{},super::super::allocation::NativeDecodeAllocationAdmission::Refused(outcome)=>{*frame.outcome=Some(outcome);frame.phase=Phase::EffectFinished},super::super::allocation::NativeDecodeAllocationAdmission::Pending=>return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}}}}}
  if frame.phase()==Phase::EffectStarted&&frame.child.is_none(){
   if frame.allocation_progress().is_some_and(|state|matches!(state.phase(),super::super::allocation::NativeDecodeAllocationPhase::QuoteStarted|super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused)){if !frame.recover_allocation_callback(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}}
   if frame.allocation_progress().is_some_and(|state|state.phase()==super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused){frame.finish_allocation(self)?}else if !frame.drive_original_producer(self,authority,invoke)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}
  }
  self.finish_effect_poll(frame)
 }
 fn finish_effect_poll<E:NativeReceivingEffectError>(&mut self,frame:&mut NativeReceivingEffect<E>)->Result<NativeReceivingEffectPoll<E>,ValueError>{
  use NativeReceivingEffectPhase as Phase;
  if frame.child_work().is_some(){if !frame.work_is_settled(){if !(if frame.work_commit_is_pending(){frame.retry_original_work(self)?}else{frame.settle_original_work(self)?}){return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}}}
  if frame.phase()==Phase::EffectStarted{
   if let Some(progress)=frame.allocation_progress(){
    if matches!(progress.phase(),super::super::allocation::NativeDecodeAllocationPhase::QuoteStarted|super::super::allocation::NativeDecodeAllocationPhase::SettlementStarted|super::super::allocation::NativeDecodeAllocationPhase::QuoteRefused){if !frame.recover_allocation_callback(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}}
    if frame.child_work().is_none()&&frame.allocation_progress().is_some_and(|progress|!progress.operation_started()&&progress.phase()==super::super::allocation::NativeDecodeAllocationPhase::QuoteAccepted){return Ok(NativeReceivingEffectPoll::Pending{work:0})}
    frame.finish_allocation(self)?;if frame.phase()==Phase::EffectStarted{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}
   }else if frame.child_work().is_some(){frame.finish_unallocated(self)?}else{return Ok(NativeReceivingEffectPoll::Pending{work:0})}
  }
  if frame.phase()==Phase::EffectFinished{if frame.child_work().is_none(){frame.cancel_unperformed_work(self)?}frame.receipt(self)?}
  if frame.phase()==Phase::ReceiptStarted&&!frame.recover_receipt(self)?{return Ok(NativeReceivingEffectPoll::Pending{work:frame.claim_child_work()})}
  Ok(NativeReceivingEffectPoll::Complete(frame.take(self)?))
 }
}
